static bool socket_write(ft_socket*s,const void*data,size_t size){const unsigned char*p=data;while(size){int n=s->ssl?SSL_write(s->ssl,p,(int)size):(int)send(s->fd,p,size,0);if(n<=0){if(!s->ssl&&errno==EINTR)continue;return false;}p+=n;size-=(size_t)n;}return true;}
static bool socket_read(ft_socket*s,void*data,size_t size){unsigned char*p=data;while(size){int n=s->ssl?SSL_read(s->ssl,p,(int)size):(int)recv(s->fd,p,size,0);if(n<=0){if(!s->ssl&&errno==EINTR)continue;return false;}p+=n;size-=(size_t)n;}return true;}
void ft_socket_close(ft_socket*s){if(s->ssl)SSL_free(s->ssl);if(s->ctx)SSL_CTX_free(s->ctx);if(s->fd>=0)close(s->fd);s->fd=-1;s->ssl=NULL;s->ctx=NULL;}
bool ft_socket_open(ft_socket*s,const char*url,const char*path,const char*header_name,const char*token,const char*ca_file,bool allow_local){memset(s,0,sizeof(*s));s->fd=-1;bool tls=!strncmp(url,"https://",8);const char*start=tls?url+8:!strncmp(url,"http://",7)?url+7:NULL;if(!start||strchr(start,'/')||strchr(start,'\r')||strchr(start,'\n')||strchr(path,'\r')||strchr(path,'\n')||strchr(token,'\r')||strchr(token,'\n'))return false;char host[256],port[16];const char*colon=strrchr(start,':');size_t hostlen=colon?(size_t)(colon-start):strlen(start);if(hostlen==0||hostlen>=sizeof(host))return false;memcpy(host,start,hostlen);host[hostlen]=0;snprintf(port,sizeof(port),"%s",colon?colon+1:tls?"443":"80");bool local=!strcmp(host,"127.0.0.1")||!strcmp(host,"localhost");if(!tls&&!(allow_local&&local))return false;
 struct addrinfo hints={.ai_family=AF_UNSPEC,.ai_socktype=SOCK_STREAM},*addresses=NULL;if(getaddrinfo(host,port,&hints,&addresses)!=0)return false;for(struct addrinfo*a=addresses;a;a=a->ai_next){int fd=socket(a->ai_family,a->ai_socktype,a->ai_protocol);if(fd<0)continue;int flags=fcntl(fd,F_GETFL,0);fcntl(fd,F_SETFL,flags|O_NONBLOCK);int result=connect(fd,a->ai_addr,a->ai_addrlen);if(result<0&&errno==EINPROGRESS){struct pollfd p={.fd=fd,.events=POLLOUT};if(poll(&p,1,5000)>0){socklen_t len=sizeof(result);if(getsockopt(fd,SOL_SOCKET,SO_ERROR,&result,&len)!=0)result=-1;}else result=-1;}if(result==0){fcntl(fd,F_SETFL,flags);s->fd=fd;break;}close(fd);}freeaddrinfo(addresses);if(s->fd<0)return false;struct timeval timeout={.tv_sec=10};setsockopt(s->fd,SOL_SOCKET,SO_RCVTIMEO,&timeout,sizeof(timeout));setsockopt(s->fd,SOL_SOCKET,SO_SNDTIMEO,&timeout,sizeof(timeout));
 if(tls){s->ctx=SSL_CTX_new(TLS_client_method());if(!s->ctx||SSL_CTX_load_verify_locations(s->ctx,ca_file,NULL)!=1)goto fail;SSL_CTX_set_verify(s->ctx,SSL_VERIFY_PEER,NULL);s->ssl=SSL_new(s->ctx);if(!s->ssl||SSL_set_fd(s->ssl,s->fd)!=1||SSL_set_tlsext_host_name(s->ssl,host)!=1)goto fail;unsigned char ip[16];if(inet_pton(AF_INET,host,ip)==1){if(X509_VERIFY_PARAM_set1_ip_asc(SSL_get0_param(s->ssl),host)!=1)goto fail;}else if(SSL_set1_host(s->ssl,host)!=1)goto fail;if(SSL_connect(s->ssl)!=1)goto fail;}
 unsigned char random[16];if(RAND_bytes(random,sizeof(random))!=1)goto fail;char*key=ft_base64(random,sizeof(random),false);if(!key)goto fail;char request[2048];int count=snprintf(request,sizeof(request),"GET %s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n%s: %s\r\n\r\n",path,start,key,header_name,token);char accept_source[128];snprintf(accept_source,sizeof(accept_source),"%s258EAFA5-E914-47DA-95CA-C5AB0DC85B11",key);free(key);if(count<=0||(size_t)count>=sizeof(request)||!socket_write(s,request,(size_t)count))goto fail;char headers[8192];size_t used=0;while(used+1<sizeof(headers)){if(!socket_read(s,headers+used,1))goto fail;used++;if(used>=4&&!memcmp(headers+used-4,"\r\n\r\n",4))break;}headers[used]=0;unsigned char digest[20];SHA1((unsigned char*)accept_source,strlen(accept_source),digest);char*expected=ft_base64(digest,sizeof(digest),false);bool ok=false;if(expected&&(!strncmp(headers,"HTTP/1.1 101 ",13)||!strncmp(headers,"HTTP/1.1 101\r",13))){const char*line=strstr(headers,"\r\n");while(line){line+=2;const char*end=strstr(line,"\r\n");if(!end)break;if(!strncasecmp(line,"Sec-WebSocket-Accept:",21)){const char*value=line+21;while(*value==' ')value++;ok=(size_t)(end-value)==strlen(expected)&&!memcmp(value,expected,strlen(expected));break;}line=end;}}free(expected);if(ok)return true;
fail:ft_socket_close(s);return false;
}
bool ft_socket_send(ft_socket*s,unsigned char opcode,const void*body,size_t length){if(length>262144||s->fd<0)return false;unsigned char header[14],mask[4];if(RAND_bytes(mask,4)!=1)return false;size_t n=2;header[0]=(unsigned char)(0x80|opcode);if(length<126)header[1]=(unsigned char)(0x80|length);else if(length<65536){header[1]=0xfe;header[n++]=(unsigned char)(length>>8);header[n++]=(unsigned char)length;}else{header[1]=0xff;for(int i=7;i>=0;i--)header[n++]=(unsigned char)((uint64_t)length>>(i*8));}memcpy(header+n,mask,4);n+=4;unsigned char*payload=length?malloc(length):NULL;if(length&&!payload)return false;for(size_t i=0;i<length;i++)payload[i]=((const unsigned char*)body)[i]^mask[i%4];bool ok=socket_write(s,header,n)&&(!length||socket_write(s,payload,length));free(payload);return ok;}
int ft_socket_receive(ft_socket*s,unsigned char**body,size_t*size){*body=NULL;*size=0;struct pollfd p={.fd=s->fd,.events=POLLIN};if((!s->ssl||SSL_pending(s->ssl)==0)&&poll(&p,1,100)<=0)return 0;unsigned char header[2];if(!socket_read(s,header,2))return -1;unsigned char opcode=header[0]&15;if(!(header[0]&128)||(header[0]&112)||(header[1]&128))return -1;uint64_t length=header[1]&127;if(length==126){unsigned char ext[2];if(!socket_read(s,ext,2))return -1;length=((uint64_t)ext[0]<<8)|ext[1];}else if(length==127){unsigned char ext[8];if(!socket_read(s,ext,8))return -1;length=0;for(int i=0;i<8;i++)length=(length<<8)|ext[i];}if(length>262144||(opcode>=8&&length>125))return -1;unsigned char*payload=calloc(1,(size_t)length+1);if(!payload)return -1;if(length&&!socket_read(s,payload,(size_t)length)){free(payload);return -1;}if(opcode==8){free(payload);return -1;}if(opcode==9){bool ok=ft_socket_send(s,10,payload,(size_t)length);free(payload);return ok?0:-1;}if(opcode==10){free(payload);return 0;}if(opcode!=1){free(payload);return -1;}*body=payload;*size=(size_t)length;return 1;}
